import numpy as np

def weidmann_velocity(rho: np.ndarray,
                      v0: float = 1.34,
                      gamma: float = 1.913,
                      rho_jam: float = 5.4) -> np.ndarray:
    """Weidmann fundamental diagram (1-D version)."""
    v = v0 * (1.0 - np.exp(-gamma * (1.0 / np.clip(rho, 1e-6, None) - 1.0 / rho_jam)))
    return np.clip(v, 0, None)

